import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.B5WAEDB7.js";const h=JSON.parse('{"title":"Konto und Anmeldung","description":"Konto anlegen, anmelden, Passwort zurücksetzen, Profil und Löschen des Kontos.","frontmatter":{"title":"Konto und Anmeldung","description":"Konto anlegen, anmelden, Passwort zurücksetzen, Profil und Löschen des Kontos."},"headers":[],"relativePath":"erste-schritte/konto-und-anmeldung.md","filePath":"erste-schritte/konto-und-anmeldung.md","lastUpdated":1788446198000}'),s={name:"erste-schritte/konto-und-anmeldung.md"};function a(o,e,l,d,g,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="konto-und-anmeldung" tabindex="-1">Konto und Anmeldung <a class="header-anchor" href="#konto-und-anmeldung" aria-label="Permalink to &quot;Konto und Anmeldung&quot;">​</a></h1><h2 id="konto-anlegen" tabindex="-1">Konto anlegen <a class="header-anchor" href="#konto-anlegen" aria-label="Permalink to &quot;Konto anlegen&quot;">​</a></h2><p>Rufen Sie <a href="https://app.apptivegrid.de" target="_blank" rel="noreferrer">app.apptivegrid.de</a> auf. Wer nicht angemeldet ist, landet auf der Anmeldeseite; dort führt neben <em>Du hast noch keinen Account?</em> die Schaltfläche <strong>Registrieren</strong> weiter:</p><blockquote><p><strong>Account erstellen</strong><em>Keine Kreditkarte notwendig.</em></p></blockquote><p>Es gibt zwei Wege:</p><p><strong>Mit einem bestehenden Konto</strong> — <strong>Weiter mit Google</strong>, <strong>Weiter mit Apple</strong> oder <strong>Weiter mit Microsoft</strong>. Sie vergeben dabei kein eigenes Passwort.</p><p><strong>Mit E-Mail und Passwort</strong> — Sie tragen Ihre <strong>E-Mail Adresse</strong> ein, ergänzen <strong>Vorname</strong>, <strong>Nachname</strong> und <strong>Passwort</strong> und bestätigen mit <strong>Account erstellen</strong>.</p><p>Die Eingabeprüfung meldet <em>Pflichtfeld</em>, <em>Mindestens 3 Zeichen</em>, <em>Mindestens 8 Zeichen verwenden</em> und <em>Bitte geben Sie ein gültige E-Mail Adresse ein</em>. Schlägt das Anlegen fehl:</p><blockquote><p><em>Wir konnten mit der von Ihnen eingegebenen E-Mail und dem Passwort kein Konto erstellen. Bitte überprüfen Sie Ihre E-Mail und Ihr Passwort und versuchen Sie es erneut.</em></p></blockquote><p>Die Meldung nennt den Grund nicht. Prüfen Sie deshalb auch, ob zu der Adresse <strong>bereits ein Konto besteht</strong> — dann führt <a href="#passwort-vergessen">Passwort vergessen</a> weiter.</p><div class="tip custom-block"><p class="custom-block-title">Was das Passwort erfüllen muss</p><p>Mindestens 8 und höchstens 128 Zeichen — sonst meldet das Formular <em>Mindestens 8 Zeichen verwenden</em> beziehungsweise <em>Höchstens 128 Zeichen verwenden</em>. Großbuchstaben, Ziffern oder Sonderzeichen werden nicht verlangt; Länge schützt besser als eine erzwungene Mischung. Wählen Sie trotzdem eines, das Sie nirgends sonst verwenden — an diesem Konto hängen später alle Ihre Spaces.</p></div><p>Mit dem Anlegen stimmen Sie den Vertragsbedingungen zu:</p><blockquote><p><em>Indem du „Account erstellen&quot; oder „Weiter mit&quot; auswählst, erklärst du dein Einverständnis mit ApptiveGrids Geschäftsbedingungen, Datenschutzbestimmungen und Auftragsverarbeitungsvertrag.</em></p></blockquote><h3 id="e-mail-bestatigen" tabindex="-1">E-Mail bestätigen <a class="header-anchor" href="#e-mail-bestatigen" aria-label="Permalink to &quot;E-Mail bestätigen&quot;">​</a></h3><p>Nach dem Absenden:</p><blockquote><p><strong>Account wurde erstellt!</strong><em>Bitte prüf dein E-Mail Postfach. Wir haben dir eine E-Mail mit einem Link zur Bestätigung gesendet.</em></p></blockquote><p>Der Link in dieser E-Mail schaltet das Konto frei:</p><blockquote><p><strong>Willkommen bei ApptiveGrid!</strong><em>Dein Account ist nun bereit.</em></p></blockquote><p><strong>Weiter zum Login</strong> führt zur Anmeldung.</p><div class="tip custom-block"><p class="custom-block-title">Kommt keine E-Mail an?</p><p>Sehen Sie im Spam-Ordner nach. Bei den Wegen über Google, Apple und Microsoft entfällt dieser Schritt — dort bestätigt der jeweilige Anbieter die Adresse.</p></div><div class="warning custom-block"><p class="custom-block-title">Auf die Registrierungsseite kann man nicht verlinken</p><p>Sie ist Teil eines einmaligen Anmeldevorgangs und lässt sich nicht als eigene Adresse weitergeben. Wer sich registrieren soll, bekommt den Verweis auf <strong>app.apptivegrid.de</strong> und klickt dort <strong>Registrieren</strong>.</p><p>Sollen Personen in einen bestimmten Space, ist die <a href="/zusammenarbeit/personen-einladen">Einladung</a> der bessere Weg: Der Link aus der Einladungs-E-Mail führt durch die Registrierung und danach direkt in den Space.</p></div><h2 id="anmelden" tabindex="-1">Anmelden <a class="header-anchor" href="#anmelden" aria-label="Permalink to &quot;Anmelden&quot;">​</a></h2><p>Die Anmeldung läuft über eine eigene Seite, nicht innerhalb der Anwendung:</p><blockquote><p><strong>Einloggen</strong><em>Willkommen zurück!</em></p></blockquote><p>Entweder über <strong>Mit Google anmelden</strong>, <strong>Mit Apple anmelden</strong> und <strong>Mit Microsoft anmelden</strong> — oder mit <strong>E-Mail</strong> und <strong>Passwort</strong>.</p><p>Stimmen die Angaben nicht:</p><blockquote><p><strong>Anmeldung fehlgeschlagen</strong><em>Wir konnten Sie leider nicht anmelden. Bitte überprüfen Sie Ihre E-Mail-Adresse und Ihr Passwort.</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">Immer denselben Weg nehmen</p><p>Ein über Google, Apple oder Microsoft angelegtes Konto hat bei ApptiveGrid kein eigenes Passwort. Melden Sie sich später über dieselbe Schaltfläche an, mit der Sie das Konto angelegt haben.</p></div><div class="tip custom-block"><p class="custom-block-title">Kein Konto für Formulare nötig</p><p>Wer nur ein <a href="/formulare/formular-erstellen">Formular</a> ausfüllt oder ein <a href="/seiten/portal-veroeffentlichen">Portal</a> ansieht, braucht <strong>kein</strong> ApptiveGrid-Konto — es sei denn, der Zugriff wurde ausdrücklich beschränkt.</p><p>Ein Konto brauchen Sie erst, um selbst Grids, Formulare, Flows oder Seiten zu bauen.</p></div><h3 id="anmeldung-mit-microsoft" tabindex="-1">Anmeldung mit Microsoft <a class="header-anchor" href="#anmeldung-mit-microsoft" aria-label="Permalink to &quot;Anmeldung mit Microsoft&quot;">​</a></h3><p>Bei Geschäfts- und Schulkonten entscheidet die IT der eigenen Organisation, welche fremden Anwendungen sich anmelden dürfen. Ist das eingeschränkt, kann <strong>Mit Microsoft anmelden</strong> mit <em>Genehmigung erforderlich</em> abbrechen. Es liegt dann nicht an Ihrem Konto, sondern an einer fehlenden Freigabe in Microsoft Entra.</p><p>Die eigene Seite <a href="/erste-schritte/anmeldung-mit-microsoft">Anmeldung mit Microsoft</a> beschreibt beides: was Sie selbst tun und was Ihre IT-Abteilung freigeben muss. Sie ist zum Weitergeben gedacht.</p><h3 id="sitzung-abgelaufen" tabindex="-1">Sitzung abgelaufen <a class="header-anchor" href="#sitzung-abgelaufen" aria-label="Permalink to &quot;Sitzung abgelaufen&quot;">​</a></h3><blockquote><p><strong>Sitzung abgelaufen</strong><em>Ihre Anmeldung ist abgelaufen oder konnte nicht abgeschlossen werden.</em></p></blockquote><p>Die Anmeldeseite gehört zu einem einzelnen Anmeldevorgang. Die Meldung erscheint in zwei Fällen:</p><ul><li>Die Seite wurde <strong>direkt aufgerufen</strong>, etwa aus einem Lesezeichen auf die Anmeldeseite selbst.</li><li>Die Seite lag <strong>länger als eine halbe Stunde offen</strong>.</li></ul><p><strong>Erneut anmelden</strong> startet den Vorgang neu.</p><div class="tip custom-block"><p class="custom-block-title">Das Lesezeichen gehört auf app.apptivegrid.de</p><p>Nicht auf die Anmeldeseite. Ein Lesezeichen auf die Anmeldeseite trägt einen abgelaufenen Vorgang mit sich und führt genau auf diese Meldung.</p></div><p>Scheitert die Anmeldung aus einem anderen Grund, nennt ApptiveGrid dieselbe Empfehlung und verweist auf <strong><a href="mailto:support@apptivegrid.de" target="_blank" rel="noreferrer">support@apptivegrid.de</a></strong>. Diese Adresse steht auf jeder Seite der Anmeldung unten links.</p><h2 id="passwort-vergessen" tabindex="-1">Passwort vergessen <a class="header-anchor" href="#passwort-vergessen" aria-label="Permalink to &quot;Passwort vergessen&quot;">​</a></h2><p>Auf der Anmeldeseite führt <strong>Passwort vergessen</strong> weiter:</p><blockquote><p><strong>Passwort vergessen</strong><em>Keine Sorge, wir senden dir ein E-Mail mit weiteren Schritten zu.</em></p></blockquote><p>Sie geben Ihre <strong>E-Mail</strong> ein und bestätigen mit <strong>Passwort zurücksetzen</strong>. Danach:</p><blockquote><p><strong>Bitte prüfe dein Postfach.</strong><em>Wir haben dir eine E-Mail gesendet.</em></p></blockquote><p>Kommt nichts an, hilft <em>Du hast keine E-Mail erhalten?</em> → <strong>Erneut senden</strong>. <strong>Zum Login</strong> führt zurück zur Anmeldung.</p><p>Der Link in der E-Mail führt auf:</p><blockquote><p><strong>Passwort zurücksetzen</strong><em>Wähle dein neues Passwort.</em></p></blockquote><p>Für das neue Passwort gelten dieselben Grenzen wie beim Anlegen: mindestens 8, höchstens 128 Zeichen.</p><p><strong>Passwort übernehmen</strong> speichert es:</p><blockquote><p><strong>Dein Passwort wurde übernommen</strong><em>Du kannst dich jetzt anmelden.</em></p></blockquote><div class="danger custom-block"><p class="custom-block-title">Den Link nicht weiterleiten</p><p>Er enthält eine Kennung, mit der das Passwort ohne weitere Prüfung gesetzt werden kann. Wer den Link hat, kommt in Ihr Konto.</p></div><div class="warning custom-block"><p class="custom-block-title">Für passwortgeschützte Links gilt das nicht</p><p>Benutzername und Passwort einer geschützten <a href="/zusammenarbeit/zugriff-beschraenken#ansichten-und-portale-benutzername-und-passwort">Ansicht oder Seite</a> sind keine ApptiveGrid-Konten. Sie lassen sich hier nicht zurücksetzen, sondern nur von der Person neu vergeben, die den Link angelegt hat.</p></div><h2 id="beim-start" tabindex="-1">Beim Start <a class="header-anchor" href="#beim-start" aria-label="Permalink to &quot;Beim Start&quot;">​</a></h2><p>Nach der ersten Anmeldung fragt ApptiveGrid:</p><blockquote><p><em>In welchem Bereich möchtest du ApptiveGrid einsetzen?</em></p></blockquote><p>Zur Auswahl stehen <strong>Privat</strong>, <strong>Arbeit</strong> und <strong>Sonstiges</strong>.</p><p>Danach begrüßt Sie die Space-Übersicht — je nach Tageszeit mit <em>Guten Morgen</em>, <em>Hallo</em>, <em>Willkommen</em> oder <em>Guten Abend</em>.</p><h2 id="angemeldetes-konto-prufen" tabindex="-1">Angemeldetes Konto prüfen <a class="header-anchor" href="#angemeldetes-konto-prufen" aria-label="Permalink to &quot;Angemeldetes Konto prüfen&quot;">​</a></h2><p>An geteilten Geräten kann es passieren, dass noch jemand anderes angemeldet ist. ApptiveGrid weist darauf hin:</p><blockquote><p><em>Sie sind als {E-Mail} angemeldet.</em><em>Bitte fahren Sie nur fort, wenn dies Ihr eigenes Konto ist.</em></p></blockquote><p>Mit <strong>Ja, ich bin {Name} - weiter</strong> bestätigen Sie, mit <strong>Anderes Konto verwenden</strong> wechseln Sie.</p><div class="tip custom-block"><p class="custom-block-title">Dieselbe Prüfung für Formulare und Seiten</p><p>Bei <a href="/formulare/formular-erstellen">Formularen</a> und <a href="/seiten/seitenlayout">Seiten</a> gibt es die Einstellung <em>Richtiges Konto bestätigen</em> beziehungsweise <em>Hinweis zur Konto-Bestätigung anzeigen</em>.</p><p>Für Anwendungen an Werkstatt-, Empfangs- oder Schulungsrechnern lohnt sich das — sonst werden Einträge unter fremdem Namen abgesendet.</p></div><h2 id="profil" tabindex="-1">Profil <a class="header-anchor" href="#profil" aria-label="Permalink to &quot;Profil&quot;">​</a></h2><p>Über <strong>Profil &amp; Einstellungen</strong> → <strong>Profil</strong>:</p><table tabindex="0"><thead><tr><th>Angabe</th><th></th></tr></thead><tbody><tr><td><strong>Profilbild</strong></td><td>Ihr Bild</td></tr><tr><td><strong>Vorname</strong>, <strong>Nachname</strong></td><td>Name, der anderen angezeigt wird</td></tr><tr><td><strong>E-Mail</strong></td><td>Ihre Adresse</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Für Profilbilder gilt eine Beschränkung</p><p><em>Wähle ein Bild mit dem Format jpg.</em> und <em>Die Datei ist zu groß. Wähle ein Bild kleiner als 1MB.</em></p></div><p>Ihr Name erscheint in der Spalte <strong>Erstellt von</strong> und im <a href="/grids/versionsverlauf">Versionsverlauf</a> — für andere Personen im Space nachvollziehbar.</p><h2 id="konto-einstellungen-und-space-einstellungen" tabindex="-1">Konto-Einstellungen und Space-Einstellungen <a class="header-anchor" href="#konto-einstellungen-und-space-einstellungen" aria-label="Permalink to &quot;Konto-Einstellungen und Space-Einstellungen&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Eine häufige Verwechslung</p><table tabindex="0"><thead><tr><th>Bereich</th><th>Gilt für</th></tr></thead><tbody><tr><td><strong>Profil &amp; Einstellungen</strong></td><td>Sie persönlich — Profil, Abrechnung, API-Zugangsdaten</td></tr><tr><td><strong>Space Einstellungen</strong></td><td>Einen Space — Tarif, Sitzplätze, Webhooks, Links</td></tr></tbody></table><p>Der Tarif wird je <strong>Space</strong> gebucht, die Zahlungsdaten hängen aber am <strong>Konto</strong>.</p></div><p>→ <a href="/spaces/einstellungen">Space-Einstellungen</a></p><h2 id="abrechnung" tabindex="-1">Abrechnung <a class="header-anchor" href="#abrechnung" aria-label="Permalink to &quot;Abrechnung&quot;">​</a></h2><p>Unter <strong>Abrechnung</strong>:</p><blockquote><p><em>Verwalte Abonnements, lade Rechnungen und bearbeite Zahlungs- oder Rechnungsdaten</em></p></blockquote><p>Die Schaltfläche <strong>Rechnungen und Abonnement</strong> führt zum Zahlungsanbieter.</p><h2 id="api-zugangsdaten" tabindex="-1">API-Zugangsdaten <a class="header-anchor" href="#api-zugangsdaten" aria-label="Permalink to &quot;API-Zugangsdaten&quot;">​</a></h2><p>Unter <strong>API Zugangsdaten</strong> erzeugen Sie Schlüssel für den Zugriff über die Programmierschnittstelle.</p><div class="danger custom-block"><p class="custom-block-title">Persönlich und weitreichend</p><blockquote><p><em>Ihre persönlichen API Anmeldeinformationen gewähren Zugriff auf alle Daten in Ihren Spaces. Geben Sie diese Anmeldeinformationen nur an Dienste und Anwendungen von Drittanbietern weiter, denen Sie vertrauen.</em></p></blockquote></div><p>→ <a href="/integrationen/api-zugangsdaten">API-Zugangsdaten</a></p><h2 id="hilfe" tabindex="-1">Hilfe <a class="header-anchor" href="#hilfe" aria-label="Permalink to &quot;Hilfe&quot;">​</a></h2><p>Über <strong>Hilfe &amp; Support</strong>:</p><table tabindex="0"><thead><tr><th>Eintrag</th><th>Zweck</th></tr></thead><tbody><tr><td><strong>Hilfe-Center</strong></td><td>Dokumentation</td></tr><tr><td><strong>Chatte mit uns</strong></td><td>Direkter Kontakt zum Support</td></tr><tr><td><strong>Senden Sie uns Feedback</strong></td><td>Rückmeldung zum Produkt</td></tr><tr><td><strong>Was ist neu?</strong></td><td>Neuerungen</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Der Chat ist der schnellste Weg</p><p>Bei Fragen, die diese Dokumentation nicht beantwortet — etwa zur Einrichtung einer Integration oder zu Tarifdetails — führt der Chat direkt zum Support.</p></div><p>Erscheint ein Hinweis auf eine neue Programmversion, laden Sie die Seite neu.</p><h2 id="vorabfunktionen" tabindex="-1">Vorabfunktionen <a class="header-anchor" href="#vorabfunktionen" aria-label="Permalink to &quot;Vorabfunktionen&quot;">​</a></h2><p>Im Profil gibt es einen Schalter mit dem Text <em>Teste unsere neuesten Funktionen</em>.</p><div class="warning custom-block"><p class="custom-block-title">Nur zum Ausprobieren</p><p>Damit werden Funktionen sichtbar, die noch in Entwicklung sind. Sie können sich ändern oder wieder verschwinden.</p><p>Verlassen Sie sich in Anleitungen für Ihr Team nicht darauf, und lassen Sie den Schalter im produktiven Einsatz aus.</p></div><h2 id="konto-loschen" tabindex="-1">Konto löschen <a class="header-anchor" href="#konto-loschen" aria-label="Permalink to &quot;Konto löschen&quot;">​</a></h2><p>Unter <strong>Profil</strong> → <strong>Account löschen</strong>.</p><div class="danger custom-block"><p class="custom-block-title">Endgültig</p><blockquote><p><em>Ihr Account und alle Daten werden unwiderruflich gelöscht. Geben Sie DELETE in das Textfeld ein um fortzufahren.</em></p></blockquote><p>Sie müssen zur Bestätigung <code>DELETE</code> eintippen. Es gibt keine Wiederherstellung.</p><p><strong>Vorher prüfen:</strong> Sind Sie Eigentümer von Spaces, die andere weiterhin brauchen? Übertragen Sie diese vorher oder sichern Sie die Daten über einen <a href="/grids/csv-export">CSV-Export</a>.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/erste-schritte/was-ist-apptivegrid">Was ist ApptiveGrid</a></li><li><a href="/erste-schritte/oberflaeche">Die Oberfläche im Überblick</a></li><li><a href="/zusammenarbeit/rollen">Rollen</a></li></ul>',91)])])}const m=n(s,[["render",a]]);export{h as __pageData,m as default};
